package e.e.a;
import android.content.Context;import android.database.Cursor;import android.net.Uri;import android.os.Bundle;import android.provider.DocumentsContract;import java.util.*;
/** Only a complete provider directory response may remove a saved history entry. */
public final class DownloadFiles118 {
 static Set<String> listed(Context c,String value){try{Uri tree=Uri.parse(value);Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(tree,DocumentsContract.getTreeDocumentId(tree));try(Cursor rows=c.getContentResolver().query(children,new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID},null,null,null)){if(rows==null)return null;Bundle extra=rows.getExtras();if(extra!=null&&(extra.getBoolean(DocumentsContract.EXTRA_LOADING,false)||extra.getString(DocumentsContract.EXTRA_ERROR)!=null))return null;Set<String> ids=new HashSet<>();while(rows.moveToNext()){String id=rows.getString(0);if(id==null)return null;ids.add(id);}return ids;}}catch(Exception e){return null;}}
 static void reconcile(Context c){Map<String,Set<String>> trees=new HashMap<>();for(DownloadJobs115.Job j:DownloadJobs115.all()){String uri=j.uri,tree=j.tree;if(!"保存済み".equals(j.phase)||uri.isEmpty())continue;try{if(!trees.containsKey(tree))trees.put(tree,listed(c,tree));Set<String> files=trees.get(tree);if(files==null||files.contains(DocumentsContract.getDocumentId(Uri.parse(uri))))continue;synchronized(DownloadJobs115.class){if("保存済み".equals(j.phase)&&uri.equals(j.uri)&&Objects.equals(tree,j.tree)&&DownloadJobs115.jobs.remove(j))DownloadJobs115.changed(c);}}catch(Exception ignored){}}}
 static boolean forget(Context c,DownloadJobs115.Job j){synchronized(DownloadJobs115.class){if(!Arrays.asList("エラー","キャンセル").contains(j.phase)||DownloadWorker115.running(j))return false;DownloadWorker115.unqueue(j);if(!DownloadJobs115.jobs.remove(j))return false;DownloadJobs115.changed(c);return true;}}
}
